/** @type {import('ts-jest').JestConfigWithTsJest} */
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  testMatch: ['**/tests/**/*.test.ts'],
  verbose: true,
  forceExit: true,
  clearMocks: true,
  resetMocks: true,
  restoreMocks: true,
};

export enum SpotType {
  STANDARD = "STANDARD",
  EV_CHARGING = "EV_CHARGING",
  HANDICAPPED = "HANDICAPPED",
  VIP = "VIP"
}

export enum ReservationStatus {
  CONFIRMED = "CONFIRMED",
  CANCELLED = "CANCELLED"
}

export interface CreateReservationDTO {
  spotId: string;
  requesterName: string;
  licensePlate?: string;
  startTime: string; // ISO 8601 string
  endTime: string;   // ISO 8601 string
}

export interface CreateSpotDTO {
  code: string;
  name: string;
  type?: SpotType;
  location: string;
}

export interface QueryReservationsDTO {
  spotId?: string;
  from?: string;
  to?: string;
  status?: ReservationStatus;
}

import { PrismaClient } from '@prisma/client';

export const prisma = new PrismaClient();

export default prisma;

import prisma from './db';
import { SpotType, ReservationStatus } from '../types';

export async function seedDatabase() {
  const existingSpotsCount = await prisma.parkingSpot.count();
  if (existingSpotsCount > 0) {
    console.log('Database already initialized with seed data.');
    return;
  }

  console.log('Seeding initial database state...');

  const spots = [
    { code: 'P-101', name: 'A-01 Normál', type: SpotType.STANDARD, location: '1. Emelet - A Zóna' },
    { code: 'P-102', name: 'A-02 Normál', type: SpotType.STANDARD, location: '1. Emelet - A Zóna' },
    { code: 'P-103', name: 'A-03 Normál', type: SpotType.STANDARD, location: '1. Emelet - A Zóna' },
    { code: 'P-104', name: 'A-04 Normál', type: SpotType.STANDARD, location: '1. Emelet - A Zóna' },
    { code: 'P-201', name: 'E-01 Elektromos Töltő (22kW)', type: SpotType.EV_CHARGING, location: '1. Emelet - EV Zóna' },
    { code: 'P-202', name: 'E-02 Elektromos Töltő (50kW Fast)', type: SpotType.EV_CHARGING, location: '1. Emelet - EV Zóna' },
    { code: 'P-301', name: 'H-01 Mozgáskorlátozott', type: SpotType.HANDICAPPED, location: 'Földszint - Bejárat mellett' },
    { code: 'P-302', name: 'H-02 Mozgáskorlátozott', type: SpotType.HANDICAPPED, location: 'Földszint - Bejárat mellett' },
    { code: 'P-401', name: 'V-01 VIP Vezetői Hely', type: SpotType.VIP, location: '2. Emelet - VIP Zóna' },
    { code: 'P-402', name: 'V-02 VIP Vezetői Hely', type: SpotType.VIP, location: '2. Emelet - VIP Zóna' },
  ];

  const createdSpots = [];
  for (const s of spots) {
    const spot = await prisma.parkingSpot.create({
      data: s,
    });
    createdSpots.push(spot);
  }

  // Create sample initial bookings for demonstration
  const now = new Date();

  // Tomorrow 09:00 - 17:00
  const tomorrowStart = new Date(now);
  tomorrowStart.setDate(tomorrowStart.getDate() + 1);
  tomorrowStart.setHours(9, 0, 0, 0);

  const tomorrowEnd = new Date(tomorrowStart);
  tomorrowEnd.setHours(17, 0, 0, 0);

  // Day after tomorrow 10:00 - 14:00
  const dayAfterStart = new Date(now);
  dayAfterStart.setDate(dayAfterStart.getDate() + 2);
  dayAfterStart.setHours(10, 0, 0, 0);

  const dayAfterEnd = new Date(dayAfterStart);
  dayAfterEnd.setHours(14, 0, 0, 0);

  await prisma.reservation.create({
    data: {
      spotId: createdSpots[0].id,
      requesterName: 'Kovács Péter',
      licensePlate: 'ABC-123',
      startTime: tomorrowStart,
      endTime: tomorrowEnd,
      status: ReservationStatus.CONFIRMED,
    },
  });

  await prisma.reservation.create({
    data: {
      spotId: createdSpots[4].id, // EV charging spot
      requesterName: 'Nagy Anna (Tesla)',
      licensePlate: 'EV-999-AA',
      startTime: dayAfterStart,
      endTime: dayAfterEnd,
      status: ReservationStatus.CONFIRMED,
    },
  });

  console.log(`Seeding complete. Created ${createdSpots.length} parking spots and initial demo reservations.`);
}

if (require.main === module) {
  seedDatabase()
    .then(() => process.exit(0))
    .catch((err) => {
      console.error('Seed error:', err);
      process.exit(1);
    });
}

import prisma from '../database/db';
import { CreateSpotDTO } from '../types';

export class SpotService {
  static async getAllSpots(type?: string) {
    const where: any = { isActive: true };
    if (type) {
      where.type = type;
    }
    return prisma.parkingSpot.findMany({
      where,
      orderBy: { code: 'asc' },
    });
  }

  static async getSpotById(id: string) {
    return prisma.parkingSpot.findUnique({
      where: { id },
      include: {
        reservations: {
          where: { status: 'CONFIRMED' },
          orderBy: { startTime: 'asc' },
        },
      },
    });
  }

  static async createSpot(data: CreateSpotDTO) {
    const existing = await prisma.parkingSpot.findUnique({
      where: { code: data.code },
    });
    if (existing) {
      throw new Error(`A parkolóhely az alábbi kóddal már létezik: ${data.code}`);
    }

    return prisma.parkingSpot.create({
      data: {
        code: data.code,
        name: data.name,
        type: data.type || 'STANDARD',
        location: data.location,
      },
    });
  }
}

import prisma from '../database/db';
import { CreateReservationDTO, QueryReservationsDTO, ReservationStatus } from '../types';

export class ReservationError extends Error {
  public statusCode: number;
  constructor(message: string, statusCode: number = 400) {
    super(message);
    this.statusCode = statusCode;
  }
}

export class ReservationService {
  static async createReservation(data: CreateReservationDTO) {
    const { spotId, requesterName, licensePlate, startTime, endTime } = data;

    if (!spotId || !requesterName || !startTime || !endTime) {
      throw new ReservationError('A parkolóhely, kérelmező neve, kezdő és záró időpont megadása kötelező.', 400);
    }

    const start = new Date(startTime);
    const end = new Date(endTime);

    if (isNaN(start.getTime()) || isNaN(end.getTime())) {
      throw new ReservationError('Érvénytelen dátum formátum (ISO-8601 elvárt).', 400);
    }

    if (start >= end) {
      throw new ReservationError('A kezdő időpontnak korábbinak kell lennie a záró időpontnál.', 400);
    }

    // Use Prisma transaction to ensure race-condition safety
    return prisma.$transaction(async (tx) => {
      // 1. Verify spot existence and active status
      const spot = await tx.parkingSpot.findUnique({
        where: { id: spotId },
      });

      if (!spot || !spot.isActive) {
        throw new ReservationError('A megadott parkolóhely nem található vagy inaktív.', 444);
      }

      // 2. Check overlap logic: start < existing.endTime AND end > existing.startTime AND status == CONFIRMED
      const overlappingReservations = await tx.reservation.findMany({
        where: {
          spotId,
          status: ReservationStatus.CONFIRMED,
          startTime: { lt: end },
          endTime: { gt: start },
        },
      });

      if (overlappingReservations.length > 0) {
        const overlap = overlappingReservations[0];
        const formattedStart = new Date(overlap.startTime).toLocaleString('hu-HU');
        const formattedEnd = new Date(overlap.endTime).toLocaleString('hu-HU');
        throw new ReservationError(
          `A parkolóhely már foglalt a megadott időintervallumban (Ütközés: ${formattedStart} - ${formattedEnd}).`,
          409
        );
      }

      // 3. Create confirmed reservation
      const reservation = await tx.reservation.create({
        data: {
          spotId,
          requesterName: requesterName.trim(),
          licensePlate: licensePlate ? licensePlate.trim().toUpperCase() : null,
          startTime: start,
          endTime: end,
          status: ReservationStatus.CONFIRMED,
        },
        include: {
          spot: true,
        },
      });

      return reservation;
    });
  }

  static async getReservations(query: QueryReservationsDTO) {
    const { spotId, from, to, status } = query;
    const where: any = {};

    if (spotId) {
      where.spotId = spotId;
    }

    if (status) {
      where.status = status;
    }

    if (from || to) {
      where.AND = [];
      if (from) {
        where.AND.push({ endTime: { gte: new Date(from) } });
      }
      if (to) {
        where.AND.push({ startTime: { lte: new Date(to) } });
      }
    }

    return prisma.reservation.findMany({
      where,
      include: {
        spot: true,
      },
      orderBy: { startTime: 'asc' },
    });
  }

  static async getReservationById(id: string) {
    const reservation = await prisma.reservation.findUnique({
      where: { id },
      include: { spot: true },
    });

    if (!reservation) {
      throw new ReservationError('A foglalás nem található.', 404);
    }

    return reservation;
  }

  static async cancelReservation(id: string) {
    const existing = await prisma.reservation.findUnique({
      where: { id },
    });

    if (!existing) {
      throw new ReservationError('A törölni kívánt foglalás nem található.', 404);
    }

    if (existing.status === ReservationStatus.CANCELLED) {
      throw new ReservationError('Ez a foglalás már korábban le lett mondva.', 400);
    }

    return prisma.reservation.update({
      where: { id },
      data: { status: ReservationStatus.CANCELLED },
      include: { spot: true },
    });
  }
}

import { Request, Response, NextFunction } from 'express';
import { SpotService } from '../services/spotService';

export class SpotController {
  static async getAllSpots(req: Request, res: Response, next: NextFunction) {
    try {
      const type = req.query.type as string | undefined;
      const spots = await SpotService.getAllSpots(type);
      res.json({ success: true, count: spots.length, data: spots });
    } catch (error) {
      next(error);
    }
  }

  static async getSpotById(req: Request, res: Response, next: NextFunction) {
    try {
      const { id } = req.params;
      const spot = await SpotService.getSpotById(id);
      if (!spot) {
        return res.status(404).json({ success: false, error: 'A parkolóhely nem található.' });
      }
      res.json({ success: true, data: spot });
    } catch (error) {
      next(error);
    }
  }

  static async createSpot(req: Request, res: Response, next: NextFunction) {
    try {
      const { code, name, type, location } = req.body;
      if (!code || !name || !location) {
        return res.status(400).json({ success: false, error: 'Kód, név és elhelyezkedés megadása kötelező.' });
      }
      const newSpot = await SpotService.createSpot({ code, name, type, location });
      res.status(201).json({ success: true, data: newSpot });
    } catch (error: any) {
      res.status(400).json({ success: false, error: error.message });
    }
  }
}

import { Request, Response, NextFunction } from 'express';
import { ReservationService, ReservationError } from '../services/reservationService';
import { ReservationStatus } from '../types';

export class ReservationController {
  static async createReservation(req: Request, res: Response, next: NextFunction) {
    try {
      const reservation = await ReservationService.createReservation(req.body);
      res.status(201).json({
        success: true,
        message: 'Foglalás sikeresen rögzítve.',
        data: reservation,
      });
    } catch (error: any) {
      if (error instanceof ReservationError) {
        return res.status(error.statusCode).json({
          success: false,
          error: error.message,
        });
      }
      next(error);
    }
  }

  static async getReservations(req: Request, res: Response, next: NextFunction) {
    try {
      const spotId = req.query.spotId as string | undefined;
      const from = req.query.from as string | undefined;
      const to = req.query.to as string | undefined;
      const status = req.query.status as ReservationStatus | undefined;

      const reservations = await ReservationService.getReservations({ spotId, from, to, status });
      res.json({
        success: true,
        count: reservations.length,
        data: reservations,
      });
    } catch (error) {
      next(error);
    }
  }

  static async getReservationById(req: Request, res: Response, next: NextFunction) {
    try {
      const { id } = req.params;
      const reservation = await ReservationService.getReservationById(id);
      res.json({ success: true, data: reservation });
    } catch (error: any) {
      if (error instanceof ReservationError) {
        return res.status(error.statusCode).json({ success: false, error: error.message });
      }
      next(error);
    }
  }

  static async cancelReservation(req: Request, res: Response, next: NextFunction) {
    try {
      const { id } = req.params;
      const cancelled = await ReservationService.cancelReservation(id);
      res.json({
        success: true,
        message: 'A foglalás sikeresen lemondva.',
        data: cancelled,
      });
    } catch (error: any) {
      if (error instanceof ReservationError) {
        return res.status(error.statusCode).json({ success: false, error: error.message });
      }
      next(error);
    }
  }
}

import { Router } from 'express';
import { SpotController } from '../controllers/spotController';

const router = Router();

router.get('/', SpotController.getAllSpots);
router.get('/:id', SpotController.getSpotById);
router.post('/', SpotController.createSpot);

export default router;

import { Router } from 'express';
import { ReservationController } from '../controllers/reservationController';

const router = Router();

router.get('/', ReservationController.getReservations);
router.get('/:id', ReservationController.getReservationById);
router.post('/', ReservationController.createReservation);
router.delete('/:id', ReservationController.cancelReservation);

export default router;

import express, { Request, Response, NextFunction } from 'express';
import cors from 'cors';
import path from 'path';
import swaggerUi from 'swagger-ui-express';
import spotRoutes from './routes/spotRoutes';
import reservationRoutes from './routes/reservationRoutes';

const app = express();

app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Serve static frontend dashboard
app.use(express.static(path.join(__dirname, '../public')));

// API Routes
app.use('/api/spots', spotRoutes);
app.use('/api/reservations', reservationRoutes);

// Swagger Documentation setup
const swaggerDocument = {
  openapi: '3.0.0',
  info: {
    title: 'Parkolóhely-foglalási Rendszer API',
    version: '1.0.0',
    description: 'Backend REST API parkolóhelyek nyilvántartására, foglalására és lemondására.',
  },
  servers: [
    {
      url: 'http://localhost:3000',
      description: 'Helyi fejlesztői szerver',
    },
  ],
  paths: {
    '/api/spots': {
      get: {
        summary: 'Parkolóhelyek listázása',
        parameters: [
          {
            name: 'type',
            in: 'query',
            schema: { type: 'string', enum: ['STANDARD', 'EV_CHARGING', 'HANDICAPPED', 'VIP'] },
            description: 'Szűrés parkolóhely típus alapján',
          },
        ],
        responses: {
          200: { description: 'Sikeres válasz' },
        },
      },
      post: {
        summary: 'Új parkolóhely felvétele',
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: {
                type: 'object',
                properties: {
                  code: { type: 'string', example: 'P-501' },
                  name: { type: 'string', example: 'B-01 Normál' },
                  type: { type: 'string', enum: ['STANDARD', 'EV_CHARGING', 'HANDICAPPED', 'VIP'] },
                  location: { type: 'string', example: '2. Emelet' },
                },
                required: ['code', 'name', 'location'],
              },
            },
          },
        },
        responses: {
          201: { description: 'Parkolóhely létrehozva' },
        },
      },
    },
    '/api/reservations': {
      get: {
        summary: 'Foglalások lekérdezése szűréssel',
        parameters: [
          { name: 'spotId', in: 'query', schema: { type: 'string' }, description: 'Parkolóhely ID' },
          { name: 'from', in: 'query', schema: { type: 'string', format: 'date-time' }, description: 'Kezdő dátum szűrő' },
          { name: 'to', in: 'query', schema: { type: 'string', format: 'date-time' }, description: 'Záró dátum szűrő' },
          { name: 'status', in: 'query', schema: { type: 'string', enum: ['CONFIRMED', 'CANCELLED'] } },
        ],
        responses: {
          200: { description: 'Sikeres lekérdezés' },
        },
      },
      post: {
        summary: 'Új foglalás rögzítése',
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: {
                type: 'object',
                properties: {
                  spotId: { type: 'string', example: 'UUID-HERE' },
                  requesterName: { type: 'string', example: 'Minta János' },
                  licensePlate: { type: 'string', example: 'ABC-123' },
                  startTime: { type: 'string', format: 'date-time', example: '2026-08-06T09:00:00.000Z' },
                  endTime: { type: 'string', format: 'date-time', example: '2026-08-06T17:00:00.000Z' },
                },
                required: ['spotId', 'requesterName', 'startTime', 'endTime'],
              },
            },
          },
        },
        responses: {
          201: { description: 'Foglalás elfogadva és rögzítve' },
          400: { description: 'Hibás kérés adat' },
          409: { description: 'Időbeli ütközés már meglévő foglalással' },
        },
      },
    },
    '/api/reservations/{id}': {
      delete: {
        summary: 'Foglalás lemondása',
        parameters: [
          { name: 'id', in: 'path', required: true, schema: { type: 'string' }, description: 'Foglalás ID' },
        ],
        responses: {
          200: { description: 'Foglalás sikeresen lemondva' },
          404: { description: 'Foglalás nem található' },
        },
      },
    },
  },
};

app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerDocument));

// Fallback error handler
app.use((err: any, req: Request, res: Response, next: NextFunction) => {
  console.error('Unhandled error:', err);
  res.status(err.status || 500).json({
    success: false,
    error: err.message || 'Belső szerverhiba történt.',
  });
});

export default app;

import app from './app';
import { seedDatabase } from './database/seed';

const PORT = process.env.PORT || 3000;

async function startServer() {
  try {
    // Seed initial database state if empty
    await seedDatabase();

    app.listen(PORT, () => {
      console.log(`====================================================`);
      console.log(`🚗 Parkolóhely-foglaló Backend Szerver Fut!`);
      console.log(`🌐 Web Dashboard: http://localhost:${PORT}`);
      console.log(`📚 API Doksi (Swagger UI): http://localhost:${PORT}/api-docs`);
      console.log(`====================================================`);
    });
  } catch (error) {
    console.error('Hiba történt a szerver indítása során:', error);
    process.exit(1);
  }
}

startServer();

:root {
  --bg-color: #0d1117;
  --panel-bg: rgba(22, 27, 34, 0.75);
  --panel-border: rgba(255, 255, 255, 0.1);
  --accent-color: #3b82f6;
  --accent-hover: #2563eb;
  --accent-glow: rgba(59, 130, 246, 0.3);
  --text-main: #f3f4f6;
  --text-muted: #9ca3af;
  --danger-color: #ef4444;
  --danger-bg: rgba(239, 68, 68, 0.15);
  --success-color: #10b981;
  --success-bg: rgba(16, 185, 129, 0.15);
  --warning-color: #f59e0b;
  --card-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Outfit', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: var(--bg-color);
  background-image: 
    radial-gradient(at 0% 0%, rgba(59, 130, 246, 0.12) 0px, transparent 50%),
    radial-gradient(at 100% 100%, rgba(16, 185, 129, 0.08) 0px, transparent 50%);
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
}

.app-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

/* Header */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--panel-border);
}

.logo-group {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.logo-icon {
  font-size: 2.5rem;
  background: var(--panel-bg);
  padding: 0.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--panel-border);
}

.app-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  background: linear-gradient(135deg, #ffffff 0%, #a5b4fc 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.header-actions {
  display: flex;
  gap: 1rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.65rem 1.25rem;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
}

.btn-primary {
  background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
  color: #fff;
  box-shadow: 0 4px 14px var(--accent-glow);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px var(--accent-glow);
}

.btn-secondary {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-main);
  border: 1px solid var(--panel-border);
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
}

.btn-danger-sm {
  background: var(--danger-bg);
  color: var(--danger-color);
  border: 1px solid rgba(239, 68, 68, 0.3);
  padding: 0.4rem 0.8rem;
  font-size: 0.85rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.btn-danger-sm:hover {
  background: rgba(239, 68, 68, 0.3);
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2.5rem;
}

.stat-card {
  background: var(--panel-bg);
  backdrop-filter: blur(12px);
  border: 1px solid var(--panel-border);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  box-shadow: var(--card-shadow);
}

.stat-icon {
  font-size: 2rem;
  width: 50px;
